/**
 * O ano extraordinário de Einstein — dois relógios, um em cada referencial.
 *
 * γ = 1 ÷ √(1 − v²/c²) é uma conta que ninguém sente. Dois ponteiros girando
 * lado a lado, um mais devagar que o outro, são a mesma coisa dita de um jeito
 * que o corpo entende: quando a nave chega a 86,6% de c, o ponteiro dela dá meia
 * volta enquanto o da Terra dá uma inteira.
 *
 * A curva de γ ao lado é o que explica por que isso só aparece "de repente": até
 * uns 50% de c ela é quase plana, e perto de c dispara. É por isso que a
 * relatividade não faz falta na vida de ninguém — e continua verdadeira.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Teto do eixo de γ no gráfico: acima disto a curva já subiu para sempre. */
const GAMA_MAX = 6;

const relatividade: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Um relógio de ponteiro, com o giro que o referencial dele permite. */
  function relogio(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    raio: number,
    voltas: number,
    rotulo: string,
    tinta: string,
  ): void {
    const cor = paleta();

    disco(ctx, cx, cy, raio, cor.contraste);
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.arc(cx, cy, raio, 0, Math.PI * 2);
    ctx.stroke();

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 12; i++) {
      const ang = (i / 12) * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(ang) * raio * 0.82, cy + Math.sin(ang) * raio * 0.82);
      ctx.lineTo(cx + Math.cos(ang) * raio * 0.94, cy + Math.sin(ang) * raio * 0.94);
      ctx.stroke();
    }

    const ang = voltas * Math.PI * 2 - Math.PI / 2;
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(ang) * raio * 0.72, cy + Math.sin(ang) * raio * 0.72);
    ctx.stroke();
    disco(ctx, cx, cy, raio * 0.09, tinta);

    texto(ctx, rotulo, cx, cy + raio * 1.42, Math.max(9, raio * 0.3), {
      cor: tinta,
      peso: 800,
    });
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const percentual = limitar(numeroDe(valores, 'v', 0), 0, 99.5);
    const beta = numeroDe(info, 'beta', percentual / 100);
    const gama = Math.max(1, numeroDe(info, 'gama', 1));
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;
    const miudo = limitar(A * 0.032, 8, 11);

    titulo(ctx, L, A, 'γ = 1 ÷ √(1 − v²/c²) — o relógio de bordo atrasa');

    // ── Os dois relógios ──────────────────────────────────────────────────
    const raio = Math.min(L * 0.13, A * 0.17);
    const cy = A * 0.36;
    // Uma volta a cada quatro segundos na Terra; o de bordo anda γ vezes menos.
    const voltas = t / 4;

    relogio(ctx, L * 0.19, cy, raio, voltas, 'Terra', cor.texto);
    relogio(ctx, L * 0.5, cy, raio, voltas / gama, 'nave', tinta);

    texto(ctx, `γ = ${gama.toFixed(2).replace('.', ',')}`, L * 0.345, cy, miudo * 1.4, {
      cor: tinta,
      peso: 800,
    });
    texto(ctx, '÷', L * 0.345, cy - miudo * 1.9, miudo * 1.2, { cor: cor.fraco, peso: 700 });

    // ── A nave, correndo em proporção à velocidade ────────────────────────
    const yNave = A * 0.63;

    // O rastro: quanto mais perto de c, mais longo.
    const comprimento = L * (0.05 + beta * 0.42);
    const xPonta = L * 0.12 + beta * L * 0.7;

    ctx.strokeStyle = tinta;
    ctx.globalAlpha = 0.35;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(xPonta - comprimento, yNave);
    ctx.lineTo(xPonta - 10, yNave);
    ctx.stroke();
    ctx.globalAlpha = 1;

    ctx.fillStyle = tinta;
    ctx.beginPath();
    ctx.moveTo(xPonta, yNave);
    ctx.lineTo(xPonta - 22, yNave - 7);
    ctx.lineTo(xPonta - 16, yNave);
    ctx.lineTo(xPonta - 22, yNave + 7);
    ctx.closePath();
    ctx.fill();

    // A linha de c, que a nave nunca alcança.
    const xLuz = L * 0.12 + L * 0.7;
    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(xLuz, yNave - A * 0.06);
    ctx.lineTo(xLuz, yNave + A * 0.05);
    ctx.stroke();
    ctx.setLineDash([]);
    texto(ctx, 'c', xLuz, yNave - A * 0.085, miudo * 1.1, { cor: cor.ouro, peso: 800 });

    texto(
      ctx,
      `${percentual.toFixed(1).replace('.', ',')}% de c`,
      L * 0.12,
      yNave + A * 0.075,
      miudo,
      { cor: cor.fraco, peso: 700, alinhamento: 'left' },
    );

    // ── A curva de γ ──────────────────────────────────────────────────────
    const gx0 = L * 0.66;
    const gx1 = L * 0.96;
    const gy0 = A * 0.16;
    const gy1 = A * 0.46;

    retangulo(ctx, gx0, gy0, gx1 - gx0, gy1 - gy0, 4, cor.palha, cor.trilho, 1);

    const cxg = (b: number): number => gx0 + b * (gx1 - gx0);
    const cyg = (g: number): number =>
      gy1 - ((limitar(g, 1, GAMA_MAX) - 1) / (GAMA_MAX - 1)) * (gy1 - gy0);

    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    for (let i = 0; i <= 100; i++) {
      const b = (i / 100) * 0.995;
      const g = 1 / Math.sqrt(Math.max(1e-9, 1 - b * b));
      if (i === 0) ctx.moveTo(cxg(b), cyg(g));
      else ctx.lineTo(cxg(b), cyg(g));
    }
    ctx.stroke();

    // A linha do alvo γ = 2.
    ctx.strokeStyle = cor.verde;
    ctx.setLineDash([3, 3]);
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(gx0, cyg(2));
    ctx.lineTo(gx1, cyg(2));
    ctx.stroke();
    ctx.setLineDash([]);
    texto(ctx, 'γ = 2', gx1 - 3, cyg(2) - miudo * 0.9, miudo * 0.85, {
      cor: cor.verde,
      peso: 700,
      alinhamento: 'right',
    });

    disco(ctx, cxg(beta), cyg(gama), 4, tinta);
    texto(ctx, 'γ', gx0 + 5, gy0 + miudo, miudo * 0.9, {
      cor: cor.fraco,
      peso: 700,
      alinhamento: 'left',
    });

    // ── O saldo do tempo ──────────────────────────────────────────────────
    texto(
      ctx,
      `12 meses na Terra = ${(12 / gama).toFixed(1).replace('.', ',')} meses na nave`,
      L / 2,
      A * 0.85,
      miudo * 1.15,
      { cor: ok ? cor.verde : cor.texto, peso: 800 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'O tempo de bordo anda pela metade ✔',
      gama < 2 ? 'Acelere: perto de c o relógio desacelera de vez.' : 'Passou do ponto.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default relatividade;
